"""Generate native timeline presentation from the independent source oracle.

Run the Thordan DLL regression with THORDAN_METADATA_EXPORT=<json path>, then:
python tools/generate_thordan_timeline.py <json path>
The production state transitions and component lifetimes remain handwritten.
"""
import json
import sys
from pathlib import Path

root = Path(__file__).resolve().parents[1]
rows = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
assert len(rows) == 335 and len({r["Id"] for r in rows}) == 335
quote = lambda s: json.dumps(s, ensure_ascii=False)
lines = [
    "// Generated by tools/generate_thordan_timeline.py from the source state graph.",
    "using MasterPlayer.Scripting;",
    "",
    "namespace MasterPlayer.Mechanics.Dungeons;",
    "",
    "internal static class ThordanTimelineMetadata",
    "{",
    "    internal static string PhaseName(int phase) => phase switch",
    "    {",
]
for phase in range(3):
    names = {r["PhaseName"] for r in rows if r["Phase"] == phase}
    assert len(names) == 1
    lines.append(f"        {phase} => {quote(names.pop())},")
lines.extend([
    '        _ => "",',
    "    };",
    "",
    "    internal static void Apply(ThordanTimelineStep step)",
    "    {",
    "        (step.Name, step.Comment, step.Hints, step.ExpectedAction) = step.Id switch",
    "        {",
])
for row in rows:
    action = int(row["Comment"].removeprefix("Cast start: ")) if row["Comment"].startswith("Cast start: ") else 0
    lines.append(f'            0x{row["Id"]:08X} => ({quote(row["Name"])}, {quote(row["Comment"])}, (ScriptTimelineHint){row["Hints"]}, {action}u),')
lines.extend([
    '            _ => throw new InvalidOperationException($"Unmapped Thordan state {step.Id:X}."),',
    "        };",
    "    }",
    "}",
    "",
])
destination = root / "Presets/Trials/Thordan/ThordanTimelineMetadata.cs"
destination.write_text("\n".join(lines), encoding="utf-8", newline="\n")
print(f"Generated {len(rows)} native timeline states.")
